def top_k_counts(words: list[str], k: int) -> list[tuple[str, int]]:
    if k <= 0:
        return []

    # Normalize words to lowercase for case-insensitive comparison
    normalized_words = [word.lower() for word in words]

    # Create a dictionary to store word counts and their first occurrence index
    word_info = {}
    for i, word in enumerate(normalized_words):
        if word not in word_info:
            word_info[word] = {"count": 0, "first_index": i}
        word_info[word]["count"] += 1

    # Sort words by count (descending) and then by first index (ascending)
    sorted_words = sorted(
        word_info.items(),
        key=lambda x: (-x[1]["count"], x[1]["first_index"])
    )

    # Select top k words and map back to original spelling
    top_k = []
    for word, info in sorted_words[:k]:
        original_spelling = words[info["first_index"]]
        top_k.append((original_spelling, info["count"]))

    return top_k
