class CycleError(Exception):
    def __init__(self, cycle):
        self.cycle = cycle
        super().__init__(f"Cycle detected: {cycle}")

def dependency_plan(nodes, edges):
    # Build adjacency list and in-degree count
    adj = {node: [] for node in nodes}
    in_deg = {node: 0 for node in nodes}

    # Process edges, skipping duplicates and self-loops
    for a, b in edges:
        if a == b:
            raise CycleError([a])  # Self-loop is a trivial cycle
        if (a, b) not in adj[a]:  # Avoid duplicate edges
            adj[a].append(b)
            in_deg[b] += 1

    # Check for unknown nodes
    for a, b in edges:
        if a not in nodes or b not in nodes:
            raise ValueError(f"Unknown node in edge: {a} -> {b}")

    # Topological sort using Kahn’s algorithm
    queue = [node for node in nodes if in_deg[node] == 0]
    order = []

    while queue:
        current = min(queue)  # Choose lexicographically smallest node
        queue.remove(current)
        order.append(current)

        for neighbor in adj[current]:
            in_deg[neighbor] -= 1
            if in_deg[neighbor] == 0:
                queue.append(neighbor)

    # Check for remaining nodes (indicates cycle)
    if len(order) != len(nodes):
        # Find a cycle by tracing back from any remaining node
        remaining = set(nodes) - set(order)
        start = next(iter(remaining))
        path = [start]
        while True:
            next_node = adj[path[-1]][0]  # Follow first edge (arbitrary choice)
            if next_node in path:
                cycle = path[path.index(next_node):] + [next_node]
                raise CycleError(cycle)
            path.append(next_node)

    return order
