import time

def retry_call(fn, attempts, retry_if, *, base_delay=0.01, sleep=time.sleep):
    if attempts <= 0:
        raise ValueError("attempts must be greater than 0")

    for n in range(attempts):
        try:
            return fn()
        except Exception as e:
            if not retry_if(e):
                raise
            if n < attempts - 1:
                delay = base_delay * (2 ** n)
                sleep(delay)

    # If all attempts fail, re-raise the last exception
    raise e
