from collections import defaultdict
from threading import Lock, Condition
from time import time
from typing import Callable, Any, Optional

class SingleFlightTTLCache:
    def __init__(self):
        self.cache = {}  # {key: (value, expiration_time)}
        self.locks = defaultdict(Lock)  # {key: Lock}
        self.conditions = defaultdict(Condition)  # {key: Condition}
        self.in_flight = {}  # {key: (loader_thread, exception)}

    def get(self, key: str) -> Optional[Any]:
        with self.locks[key]:
            if key in self.cache:
                value, expiration = self.cache[key]
                if time() < expiration:
                    return value
                else:
                    del self.cache[key]
            return None

    def set(self, key: str, value: Any, ttl: int) -> None:
        with self.locks[key]:
            self.cache[key] = (value, time() + ttl)

    def delete(self, key: str) -> None:
        with self.locks[key]:
            if key in self.cache:
                del self.cache[key]

    def __len__(self) -> int:
        return len(self.cache)

    def get_or_load(self, key: str, loader: Callable[[], Any]) -> Any:
        with self.locks[key]:
            if key in self.cache:
                value, expiration = self.cache[key]
                if time() < expiration:
                    return value
                else:
                    del self.cache[key]

            # Check if a loader is already running for this key
            if key in self.in_flight:
                loader_thread, exception = self.in_flight[key]
                if exception is not None:
                    raise exception
                else:
                    # Wait for the loader to finish
                    with self.conditions[key]:
                        self.conditions[key].wait()
                    return self.get(key)

            # No loader running, start one
            self.in_flight[key] = (None, None)
            try:
                value = loader()
                self.set(key, value, ttl=3600)  # Default TTL of 1 hour
                return value
            except Exception as e:
                self.in_flight[key] = (None, e)
                raise e
            finally:
                # Notify waiting threads
                with self.conditions[key]:
                    self.conditions[key].notify_all()
                del self.in_flight[key]
