import asyncio
from typing import List, Tuple, Any

async def run_with_deadline(coros: List[asyncio.Future], limit: int, timeout: float) -> List[Tuple[str, Any]]:
    results = [None] * len(coros)
    running = set()
    completed = 0

    async def run_next():
        nonlocal completed
        while completed < len(coros):
            if len(running) < limit:
                for i, coro in enumerate(coros):
                    if results[i] is None and i not in running:
                        running.add(i)
                        try:
                            value = await coro
                            results[i] = ("ok", value)
                        except Exception as e:
                            results[i] = ("error", e)
                        finally:
                            running.remove(i)
                            completed += 1
                            break
            else:
                await asyncio.sleep(0.1)

    async def cancel_remaining():
        for i, coro in enumerate(coros):
            if results[i] is None:
                coro.cancel()
                results[i] = ("cancelled", None)

    try:
        await asyncio.wait_for(run_next(), timeout)
    except asyncio.TimeoutError:
        await cancel_remaining()

    return results
