from collections import defaultdict
from threading import Lock, Condition
from time import sleep

class IdempotentEventProcessor:
    def __init__(self, apply_callback):
        self.apply = apply_callback
        self.results = defaultdict(lambda: {"status": "pending", "value": None})
        self.locks = defaultdict(Lock)
        self.conditions = defaultdict(Condition)

    def process(self, event_id, payload):
        with self.locks[event_id]:
            if self.results[event_id]["status"] != "pending":
                return self.results[event_id]["value"]

            try:
                result = self.apply(payload)
                self.results[event_id] = {"status": "success", "value": result}
                with self.conditions[event_id]:
                    self.conditions[event_id].notify_all()
                return result
            except Exception as e:
                self.results[event_id] = {"status": "failed", "value": str(e)}
                with self.conditions[event_id]:
                    self.conditions[event_id].notify_all()
                raise

    def result(self, event_id):
        with self.locks[event_id]:
            if self.results[event_id]["status"] == "pending":
                with self.conditions[event_id]:
                    self.conditions[event_id].wait()
            if self.results[event_id]["status"] == "success":
                return self.results[event_id]["value"]
            elif self.results[event_id]["status"] == "failed":
                raise KeyError(self.results[event_id]["value"])
            else:
                raise KeyError("Unknown status")
