import threading

class VersionedStore:
    def __init__(self):
        self._data = {}
        self._version = {}
        self._lock = threading.Lock()

    def read(self, key):
        with self._lock:
            if key not in self._data:
                return None
            return copy.deepcopy(self._data[key])

    def compare_and_set(self, key, expected_version, value):
        with self._lock:
            if key not in self._data or self._version[key] != expected_version:
                return False
            self._data[key] = copy.deepcopy(value)
            self._version[key] += 1
            return True

    def delete(self, key, expected_version):
        with self._lock:
            if key not in self._data or self._version[key] != expected_version:
                return False
            del self._data[key]
            del self._version[key]
            return True

    def snapshot(self):
        with self._lock:
            return copy.deepcopy(self._data)
