class ReplicatedLog:
    def __init__(self):
        self.entries = []
        self.commit_index = -1
        self.last_applied = -1
        self.current_term = 0

    def append(self, command):
        index = len(self.entries)
        self.entries.append((self.current_term, command))
        return index

    def receive_append(self, term, prev_index, prev_term, entries, leader_commit):
        if term < self.current_term:
            return False, -1
        if prev_index >= len(self.entries) or (prev_index > 0 and self.entries[prev_index - 1][0] != prev_term):
            return False, prev_index
        if leader_commit > len(self.entries):
            return False, -1
        self.entries[prev_index + 1:] = entries
        self.commit_index = min(leader_commit, len(self.entries) - 1)
        self.current_term = term
        return True, -1

    def commit_to(self, index):
        if index > len(self.entries) - 1:
            return
        self.commit_index = index

    def apply_committed(self):
        commands = []
        while self.last_applied < self.commit_index:
            self.last_applied += 1
            commands.append(self.entries[self.last_applied][1])
        return commands

    def current_index(self):
        return len(self.entries) - 1

    def current_term(self):
        return self.current_term
