import time
import threading
import logging
from collections import deque
from functools import wraps

# Configure logging to suppress token leakage
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)
logger.setLevel(logging.INFO)

# In-memory storage
tasks = {}
cache = {}
queue = deque()
running = False
lock = threading.Lock()

def synchronized(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        with lock:
            return func(*args, **kwargs)
    return wrapper

@synchronized
def handle(payload):
    global running
    try:
        task_id = payload["id"]
        if task_id in cache:
            return cache[task_id]
        queue.append(payload)
        if not running:
            running = True
            threading.Thread(target=process_queue).start()
        return "queued"
    except Exception as e:
        logger.error(f"Error in handle: {e}")
        return "error"

@synchronized
def process_queue():
    global running
    while queue:
        payload = queue.popleft()
        try:
            result = do_work(payload)
            cache[payload["id"]] = result
        except Exception as e:
            logger.error(f"Error processing task {payload['id']}: {e}")
    running = False

@synchronized
def do_work(payload):
    retry = 0
    while retry < 3:
        try:
            return call_api(payload)
        except Exception as e:
            retry += 1
            logger.warning(f"API call failed for {payload['id']}, retrying ({retry}/3)")
    raise Exception("Max retries exceeded")

def call_api(payload):
    # Simulate API call with timeout
    time.sleep(1)  # Simulate network delay
    if payload["id"] == "timeout":
        raise TimeoutError("API call timed out")
    return {"status": "success", "data": payload["id"]}

@synchronized
def close():
    global running
    running = False
    while queue:
        payload = queue.popleft()
        logger.warning(f"Task {payload['id']} dropped due to service closure")

# Test plan
def test_normal():
    payload = {"id": "task1", "token": "secret"}
    assert handle(payload) == "queued"
    time.sleep(2)
    assert cache["task1"] == {"status": "success", "data": "task1"}

def test_timeout():
    payload = {"id": "timeout", "token": "secret"}
    assert handle(payload) == "queued"
    time.sleep(2)
    assert "timeout" in cache
    assert cache["timeout"]["status"] == "error"

def test_retry():
    payload = {"id": "retry", "token": "secret"}
    assert handle(payload) == "queued"
    time.sleep(2)
    assert cache["retry"] == {"status": "success", "data": "retry"}

def test_duplicate():
    payload = {"id": "dup", "token": "secret"}
    assert handle(payload) == "queued"
    assert handle(payload) == "queued"
    time.sleep(2)
    assert len(cache) == 1
    assert cache["dup"] == {"status": "success", "data": "dup"}

def test_close():
    payload = {"id": "close", "token": "secret"}
    assert handle(payload) == "queued"
    close()
    time.sleep(2)
    assert "close" not in cache

def test_recovery():
    payload = {"id": "recover", "token": "secret"}
    assert handle(payload) == "queued"
    close()
    time.sleep(2)
    assert "recover" not in cache
    running = True
    process_queue()
    time.sleep(2)
    assert "recover" not in cache  # Should not recover dropped tasks

if __name__ == "__main__":
    test_normal()
    test_timeout()
    test_retry()
    test_duplicate()
    test_close()
    test_recovery()
    print("All tests passed.")
